def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_d = sum(1 for _, o in history if o == 'D')
    opp_c = n - opp_d

    recent = history[-10:]
    recent_opp_d = sum(1 for _, o in recent if o == 'D')

    if opp_c == 0:
        return 'D'
    if recent_opp_d >= 8:
        return 'D'

    after_c = 0
    coop_after_c = 0
    after_d = 0
    coop_after_d = 0

    for i in range(1, n):
        prev_me = history[i - 1][0]
        next_opp = history[i][1]
        if prev_me == 'C':
            after_c += 1
            if next_opp == 'C':
                coop_after_c += 1
        else:
            after_d += 1
            if next_opp == 'C':
                coop_after_d += 1

    c_after_c = coop_after_c / after_c if after_c >= 3 else 0.5
    c_after_d = coop_after_d / after_d if after_d >= 3 else 0.5

    if after_c + after_d >= 4:
        if c_after_c < 0.35 and c_after_d < 0.35:
            return 'D'
        if c_after_c < 0.45 and c_after_d > 0.55:
            return 'D'

    if last_opp == 'D':
        if last_me == 'C':
            return 'D'
        if c_after_c >= 0.55:
            return 'C'
        if c_after_d >= 0.65:
            return 'D'
        return 'C' if rng.random() < 0.55 else 'D'

    if last_me == 'D':
        reward_streak = 0
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'D' and history[i][1] == 'C':
                reward_streak += 1
            else:
                break

        if reward_streak >= 5:
            if recent_opp_d == 0 and n >= 90:
                return 'D'
            return 'C'

        if recent_opp_d <= 2 or n >= 80:
            return 'D'

        return 'D' if rng.random() < 0.7 else 'C'

    if after_d >= 3 and c_after_d >= 0.75 and opp_c >= opp_d and recent_opp_d <= 1:
        if n >= 85 or rng.random() < 0.10:
            return 'D'
        return 'C'

    return 'C'
